16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	import org.springframework.samples.petclinic.util.BusinessDay;
20	
21	import jakarta.persistence.*;
22	import jakarta.validation.constraints.NotEmpty;
23	import jakarta.validation.constraints.Pattern;
24	
25	import java.time.LocalDate;
26	import java.util.*;
27	
28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "address")
40	    @NotEmpty
41	    private String address;
42	
43	    @Column(name = "city")
44	    @NotEmpty
45	    private String city;
46	
47	    @Column(name = "telephone")
48	    @NotEmpty
49	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form (+ and 8 to 15 digits)")
50	    private String telephone;
51	
52	    @Column(name = "email")
53	    private String email;
54	
55	    @Column(name = "registration_date", columnDefinition = "DATE")
56	    private LocalDate registrationDate;
57	
58	    @Column(name = "customer_code")
59	    private String customerCode;
60	
61	    @Column(name = "household_id")
62	    private String householdId;
63	
64	    @Column(name = "namesake_count")
65	    private Integer namesakeCount;
66	
67	    @Column(name = "household_size")
68	    private Integer householdSize;
69	
70	    @Column(name = "bulk_signup_warning")
71	    private boolean bulkSignupWarning;
72	
73	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
74	    private Set<Pet> pets;
75	
76	    public String getAddress() {
77	        return this.address;
78	    }
79	
80	    public void setAddress(String address) {
81	        this.address = address;
82	    }
83	
84	    public String getCity() {
85	        return this.city;
86	    }
87	
88	    public void setCity(String city) {
89	        this.city = city;
90	    }
91	
92	    public String getTelephone() {
93	        return this.telephone;
94	    }
95	
96	    public void setTelephone(String telephone) {
97	        this.telephone = telephone;
98	    }
99	
100	    public String getEmail() {
101	        return this.email;
102	    }
103	
104	    /**
105	     * Stores the email in its canonical lower-cased form so it is always persisted and
106	     * returned lower-cased, regardless of the casing supplied by the client.
107	     */
108	    public void setEmail(String email) {
109	        this.email = email == null ? null : email.toLowerCase(Locale.ROOT);
110	    }
111	
112	    public LocalDate getRegistrationDate() {
113	        return this.registrationDate;
114	    }
115	
116	    public void setRegistrationDate(LocalDate registrationDate) {
117	        this.registrationDate = registrationDate;
118	    }
119	
120	    public String getCustomerCode() {
121	        return this.customerCode;
122	    }
123	
124	    public void setCustomerCode(String customerCode) {
125	        this.customerCode = customerCode;
126	    }
127	
128	    public String getHouseholdId() {
129	        return this.householdId;
130	    }
131	
132	    public void setHouseholdId(String householdId) {
133	        this.householdId = householdId;
134	    }
135	
136	    public Integer getNamesakeCount() {
137	        return this.namesakeCount;
138	    }
139	
140	    public void setNamesakeCount(Integer namesakeCount) {
141	        this.namesakeCount = namesakeCount;
142	    }
143	
144	    public Integer getHouseholdSize() {
145	        return this.householdSize;
146	    }
147	
148	    public void setHouseholdSize(Integer householdSize) {
149	        this.householdSize = householdSize;
150	    }
151	
152	    public boolean isBulkSignupWarning() {
153	        return this.bulkSignupWarning;
154	    }
155	
156	    public void setBulkSignupWarning(boolean bulkSignupWarning) {
157	        this.bulkSignupWarning = bulkSignupWarning;
158	    }
159	
160	    /**
161	     * On first persist, default the registration date to the server's current date when the
162	     * client did not supply one, then roll the effective date forward so it always falls on a
163	     * business day (a weekend moves to the following Monday).
164	     */
165	    @PrePersist
166	    private void defaultRegistrationDate() {
167	        LocalDate effectiveDate = this.registrationDate == null ? LocalDate.now() : this.registrationDate;
168	        this.registrationDate = BusinessDay.rollForward(effectiveDate);
169	    }
170	
171	    protected Set<Pet> getPetsInternal() {
172	        if (this.pets == null) {
173	            this.pets = new HashSet<>();
174	        }
175	        return this.pets;
176	    }
177	
178	    protected void setPetsInternal(Set<Pet> pets) {
179	        this.pets = pets;
180	    }
181	
182	    public List<Pet> getPets() {
183	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
184	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
185	        return Collections.unmodifiableList(sortedPets);
186	    }
187	
188	    public void setPets(List<Pet> pets) {
189	        this.pets = new HashSet<>(pets);
190	    }
191	
192	    public void addPet(Pet pet) {
193	        getPetsInternal().add(pet);
194	        pet.setOwner(this);
195	    }
196	
197	    /**
198	     * Return the Pet with the given name, or null if none found for this Owner.
199	     *
200	     * @param name to test
201	     * @return true if pet name is already in use
202	     */
203	    public Pet getPet(String name) {
204	        return getPet(name, false);
205	    }
206	
207	    /**
208	     * Return the Pet with the given name, or null if none found for this Owner.
209	     *
210	     * @param name to test
211	     * @return true if pet name is already in use
212	     */
213	    public Pet getPet(String name, boolean ignoreNew) {
214	        name = name.toLowerCase();
215	        for (Pet pet : getPetsInternal()) {
216	            if (!ignoreNew || !pet.isNew()) {
217	                String compName = pet.getName();
218	                compName = compName.toLowerCase();
219	                if (compName.equals(name)) {
220	                    return pet;
221	                }
222	            }
223	        }
224	        return null;
225	    }
226	
227	    public Pet getPet(Integer petId) {
228	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
229	    }
230	
231	    @Override
232	    public String toString() {
233	        return new ToStringCreator(this)
234	
235	            .append("id", this.getId())
236	            .append("new", this.isNew())
237	            .append("lastName", this.getLastName())
238	            .append("firstName", this.getFirstName())
239	            .append("address", this.address)
240	            .append("city", this.city)
241	            .append("telephone", this.telephone)
242	            .append("email", this.email)
243	            .toString();
244	    }
245	}
