36	/**
37	 * Mostly used as a facade for all Petclinic controllers
38	 * Also a placeholder for @Transactional and @Cacheable annotations
39	 *
40	 * @author Michael Isvy
41	 * @author Vitaliy Fedoriv
42	 */
43	@Service
44	public class ClinicServiceImpl implements ClinicService {
45	
46	    private final PetRepository petRepository;
47	    private final VetRepository vetRepository;
48	    private final OwnerRepository ownerRepository;
49	    private final VisitRepository visitRepository;
50	    private final SpecialtyRepository specialtyRepository;
51	    private final PetTypeRepository petTypeRepository;
52	    private final CustomerCodeGenerator customerCodeGenerator;
53	    private final HouseholdIdGenerator householdIdGenerator;
54	
55	    public ClinicServiceImpl(
56	        PetRepository petRepository,
57	        VetRepository vetRepository,
58	        OwnerRepository ownerRepository,
59	        VisitRepository visitRepository,
60	        SpecialtyRepository specialtyRepository,
61	        PetTypeRepository petTypeRepository,
62	        CustomerCodeGenerator customerCodeGenerator,
63	        HouseholdIdGenerator householdIdGenerator) {
64	        this.petRepository = petRepository;
65	        this.vetRepository = vetRepository;
66	        this.ownerRepository = ownerRepository;
67	        this.visitRepository = visitRepository;
68	        this.specialtyRepository = specialtyRepository;
69	        this.petTypeRepository = petTypeRepository;
70	        this.customerCodeGenerator = customerCodeGenerator;
71	        this.householdIdGenerator = householdIdGenerator;
72	    }
73	
74	    @Override
75	    @Transactional(readOnly = true)
76	    public Collection<Pet> findAllPets() throws DataAccessException {
77	        return petRepository.findAll();
78	    }
79	
80	    @Override
81	    @Transactional(readOnly = true)
82	    public Page<Pet> findPets(Pageable pageable) throws DataAccessException {
83	        return petRepository.findAll(pageable);
84	    }
85	
86	    @Override
87	    @Transactional
88	    public void deletePet(Pet pet) throws DataAccessException {
89	        petRepository.delete(pet);
90	    }
91	
92	    @Override
93	    @Transactional(readOnly = true)
94	    public Visit findVisitById(int visitId) throws DataAccessException {
95	        return findEntityById(() -> visitRepository.findById(visitId));
96	    }
97	
98	    @Override
99	    @Transactional(readOnly = true)
100	    public Collection<Visit> findAllVisits() throws DataAccessException {
101	        return visitRepository.findAll();
102	    }
103	
104	    @Override
105	    @Transactional
106	    public void deleteVisit(Visit visit) throws DataAccessException {
107	        visitRepository.delete(visit);
108	    }
109	
110	    @Override
111	    @Transactional(readOnly = true)
112	    public Vet findVetById(int id) throws DataAccessException {
113	        return findEntityById(() -> vetRepository.findById(id));
114	    }
115	
116	    @Override
117	    @Transactional(readOnly = true)
118	    public Collection<Vet> findAllVets() throws DataAccessException {
119	        return vetRepository.findAll();
120	    }
121	
122	    @Override
123	    @Transactional
124	    public void saveVet(Vet vet) throws DataAccessException {
125	        vetRepository.save(vet);
126	    }
127	
128	    @Override
129	    @Transactional
130	    public void deleteVet(Vet vet) throws DataAccessException {
131	        vetRepository.delete(vet);
132	    }
133	
134	    @Override
135	    @Transactional(readOnly = true)
136	    public Collection<Owner> findAllOwners() throws DataAccessException {
137	        return ownerRepository.findAll();
138	    }
139	
140	    @Override
141	    @Transactional(readOnly = true)
142	    public Page<Owner> findOwners(String lastName, Pageable pageable) throws DataAccessException {
143	        if (lastName != null) {
144	            return ownerRepository.findByLastName(lastName, pageable);
145	        }
146	        return ownerRepository.findAll(pageable);
147	    }
148	
149	    @Override
150	    @Transactional
151	    public void deleteOwner(Owner owner) throws DataAccessException {
152	        ownerRepository.delete(owner);
153	    }
154	
155	    @Override
156	    @Transactional(readOnly = true)
157	    public PetType findPetTypeById(int petTypeId) {
158	        return findEntityById(() -> petTypeRepository.findById(petTypeId));
159	    }
160	
161	    @Override
162	    @Transactional(readOnly = true)
163	    public Collection<PetType> findAllPetTypes() throws DataAccessException {
164	        return petTypeRepository.findAll();
165	    }
166	
167	    @Override
168	    @Transactional
169	    public void savePetType(PetType petType) throws DataAccessException {
170	        petTypeRepository.save(petType);
171	    }
172	
173	    @Override
174	    @Transactional
175	    public void deletePetType(PetType petType) throws DataAccessException {
176	        petTypeRepository.delete(petType);
177	    }
178	
179	    @Override
180	    @Transactional(readOnly = true)
181	    public Specialty findSpecialtyById(int specialtyId) {
182	        return findEntityById(() -> specialtyRepository.findById(specialtyId));
183	    }
184	
185	    @Override
186	    @Transactional(readOnly = true)
187	    public Collection<Specialty> findAllSpecialties() throws DataAccessException {
188	        return specialtyRepository.findAll();
189	    }
190	
191	    @Override
192	    @Transactional
193	    public void saveSpecialty(Specialty specialty) throws DataAccessException {
194	        specialtyRepository.save(specialty);
195	    }
196	
197	    @Override
198	    @Transactional
199	    public void deleteSpecialty(Specialty specialty) throws DataAccessException {
200	        specialtyRepository.delete(specialty);
201	    }
202	
203	    @Override
204	    @Transactional(readOnly = true)
205	    public Collection<PetType> findPetTypes() throws DataAccessException {
206	        return petRepository.findPetTypes();
207	    }
208	
209	    @Override
210	    @Transactional(readOnly = true)
211	    public Owner findOwnerById(int id) throws DataAccessException {
212	        return findEntityById(() -> ownerRepository.findById(id));
213	    }
214	
215	    @Override
216	    @Transactional(readOnly = true)
217	    public Pet findPetById(int id) throws DataAccessException {
218	        return findEntityById(() -> petRepository.findById(id));
219	    }
220	
221	    @Override
222	    @Transactional
223	    public void savePet(Pet pet) throws DataAccessException {
224	        pet.setType(findPetTypeById(pet.getType().getId()));
225	        petRepository.save(pet);
226	    }
227	
228	    @Override
229	    @Transactional
230	    public void saveVisit(Visit visit) throws DataAccessException {
231	        visitRepository.save(visit);
232	
233	    }
234	
235	    @Override
236	    @Transactional(readOnly = true)
237	    public Collection<Vet> findVets() throws DataAccessException {
238	        return vetRepository.findAll();
239	    }
240	
241	    @Override
242	    @Transactional
243	    public void saveOwner(Owner owner) throws DataAccessException {
244	        if (owner.isNew() && owner.getCustomerCode() == null) {
245	            long citySequence = ownerRepository.countByCityIgnoreCase(owner.getCity()) + 1;
246	            owner.setCustomerCode(customerCodeGenerator.generate(owner.getCity(), owner.getLastName(), citySequence));
247	        }
248	        ownerRepository.save(owner);
249	
250	    }
251	
252	    @Override
253	    @Transactional(readOnly = true)
254	    public boolean existsOwnerByTelephone(String telephone) throws DataAccessException {
255	        return ownerRepository.existsByTelephone(telephone);
256	    }
257	
258	    @Override
259	    @Transactional(readOnly = true)
260	    public boolean existsOwnerByEmail(String email) throws DataAccessException {
261	        return ownerRepository.existsByEmailIgnoreCase(email);
262	    }
263	
264	    @Override
265	    @Transactional(readOnly = true)
266	    public boolean existsOwnerInHousehold(String lastName, String address) throws DataAccessException {
267	        return !findHouseholdMembers(lastName, address).isEmpty();
268	    }
269	
270	    /**
271	     * The maximum number of owners allowed in a single city; once a city holds this many
272	     * owners it is considered at capacity and no further owners may be created there.
273	     */
274	    static final long CITY_CAPACITY = 50;
275	
276	    @Override
277	    @Transactional(readOnly = true)
278	    public boolean isCityAtCapacity(String city) throws DataAccessException {
279	        return ownerRepository.countByCityIgnoreCase(city) >= CITY_CAPACITY;
280	    }
281	
282	    /**
283	     * The maximum number of owners that may be created in a single day; once this many owners
284	     * have already been registered on a given business day no further owners may be created for
285	     * that day.
286	     */
287	    static final long DAILY_OWNER_LIMIT = 100;
288	
289	    @Override
290	    public LocalDate resolveRegistrationDate(LocalDate registrationDate) {
291	        LocalDate effectiveDate = registrationDate == null ? LocalDate.now() : registrationDate;
292	        return BusinessDay.rollForward(effectiveDate);
293	    }
294	
295	    @Override
296	    @Transactional(readOnly = true)
297	    public boolean isDailyOwnerLimitReached(LocalDate registrationDate) throws DataAccessException {
298	        return ownerRepository.countByRegistrationDate(registrationDate) >= DAILY_OWNER_LIMIT;
299	    }
300	
301	    /**
302	     * The number of owners that may be registered on a given day before further sign-ups for that
303	     * day are flagged with a bulk-signup warning. Once more than this many owners already exist for
304	     * the day, subsequent creates carry the warning.
305	     */
306	    static final long BULK_SIGNUP_WARNING_THRESHOLD = 80;
307	
308	    @Override
309	    @Transactional(readOnly = true)
310	    public boolean isBulkSignupWarranted(LocalDate registrationDate) throws DataAccessException {
311	        return ownerRepository.countByRegistrationDate(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD;
312	    }
313	
314	    @Override
315	    @Transactional(readOnly = true)
316	    public long countNamesakes(String firstName, String lastName) throws DataAccessException {
317	        return ownerRepository.findByLastNameIgnoreCase(lastName).stream()
318	            .filter(owner -> owner.getFirstName().equalsIgnoreCase(firstName))
319	            .count();
320	    }
321	
322	    @Override
323	    @Transactional
324	    public String assignHousehold(Owner owner) throws DataAccessException {
325	        List<Owner> members = findHouseholdMembers(owner.getLastName(), owner.getAddress());
326	        String householdId = members.stream()
327	            .map(Owner::getHouseholdId)
328	            .filter(Objects::nonNull)
329	            .findFirst()
330	            .orElseGet(() -> householdIdGenerator.generate(owner.getLastName(), owner.getAddress()));
331	        owner.setHouseholdId(householdId);
332	        for (Owner member : members) {
333	            if (member.getHouseholdId() == null) {
334	                member.setHouseholdId(householdId);
335	                ownerRepository.save(member);
336	            }
337	        }
338	        return householdId;
339	    }
340	
341	    /**
342	     * The number of members the owner's household will have once this (not yet persisted) owner is
343	     * created: the existing members sharing its last name and canonical address, plus the owner itself.
344	     */
345	    @Override
346	    @Transactional(readOnly = true)
347	    public long countHouseholdMembers(String lastName, String address) throws DataAccessException {
348	        return findHouseholdMembers(lastName, address).size() + 1;
349	    }
350	
351	    /**
352	     * Find the existing owners that share {@code owner}'s household, i.e. those with the same last
353	     * name (ignoring case) and the same canonical address.
354	     */
355	    private List<Owner> findHouseholdMembers(String lastName, String address) {
356	        String canonicalAddress = householdIdGenerator.canonical(address);
357	        return ownerRepository.findByLastNameIgnoreCase(lastName).stream()
358	            .filter(owner -> householdIdGenerator.canonical(owner.getAddress()).equals(canonicalAddress))
359	            .toList();
360	    }
361	
362	    @Override
363	    @Transactional(readOnly = true)
364	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
365	        return ownerRepository.findByLastName(lastName);
366	    }
367	
368	    @Override
369	    @Transactional(readOnly = true)
370	    public Collection<Visit> findVisitsByPetId(int petId) {
371	        return visitRepository.findByPetId(petId);
372	    }
373	
374	    @Override
375	    @Transactional(readOnly = true)
376	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
377	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
378	    }
379	
380	    private <T> T findEntityById(Supplier<T> supplier) {
381	        try {
382	            return supplier.get();
383	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
384	            // Just ignore not found exceptions for Jdbc/Jpa realization
385	            return null;
386	        }
387	    }
388	
389	}
