95	    @Override
96	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
97	        Owner owner = this.clinicService.findOwnerById(ownerId);
98	        if (owner == null) {
99	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
100	        }
101	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
102	    }
103	
104	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
105	    @Override
106	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
107	        HttpHeaders headers = new HttpHeaders();
108	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
109	        owner.setRegistrationDate(this.clinicService.resolveRegistrationDate(owner.getRegistrationDate()));
110	        if (this.clinicService.isDailyOwnerLimitReached(owner.getRegistrationDate())) {
111	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
112	        }
113	        if (this.clinicService.existsOwnerByTelephone(owner.getTelephone())) {
114	            return new ResponseEntity<>(HttpStatus.CONFLICT);
115	        }
116	        if (owner.getEmail() != null && !owner.getEmail().isBlank()
117	                && this.clinicService.existsOwnerByEmail(owner.getEmail())) {
118	            return new ResponseEntity<>(HttpStatus.CONFLICT);
119	        }
120	        if (this.clinicService.isCityAtCapacity(owner.getCity())) {
121	            return new ResponseEntity<>(HttpStatus.CONFLICT);
122	        }
123	        if (this.clinicService.existsOwnerInHousehold(owner.getLastName(), owner.getAddress())) {
124	            if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
125	                return new ResponseEntity<>(HttpStatus.CONFLICT);
126	            }
127	            this.clinicService.assignHousehold(owner);
128	        }
129	        owner.setNamesakeCount((int) this.clinicService.countNamesakes(owner.getFirstName(), owner.getLastName()));
130	        owner.setHouseholdSize((int) this.clinicService.countHouseholdMembers(owner.getLastName(), owner.getAddress()));
131	        owner.setBulkSignupWarning(this.clinicService.isBulkSignupWarranted(owner.getRegistrationDate()));
132	        this.clinicService.saveOwner(owner);
133	        this.ownerAuditor.auditCreated(owner);
134	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
135	        headers.setLocation(UriComponentsBuilder.newInstance()
136	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
137	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
138	    }
