1	package org.springframework.samples.petclinic.rest.validation;
2	
3	import jakarta.validation.ConstraintValidator;
4	import jakarta.validation.ConstraintValidatorContext;
5	
6	public class TelephoneValidator implements ConstraintValidator<Telephone, String> {
7	
8	    @Override
9	    public boolean isValid(String telephone, ConstraintValidatorContext context) {
10	        String e164 = TelephoneNormalizer.toE164(telephone);
11	        return e164 != null && E164NationalNumberRule.hasValidNationalLength(e164);
12	    }
13	}
