22	@Mapper(uses = PetMapper.class)
23	public interface OwnerMapper {
24	
25	    @Mapping(target = "displayName", expression = "java(formatDisplayName(owner))")
26	    @Mapping(target = "initials", expression = "java(formatInitials(owner))")
27	    @Mapping(target = "locality", expression = "java(resolveLocality(owner))")
28	    @Mapping(target = "membershipNumber", expression = "java(formatMembershipNumber(owner))")
29	    @Mapping(target = "membershipLevel", expression = "java(resolveMembershipLevel(owner))")
30	    @Mapping(target = "contactPreference", expression = "java(resolveContactPreference(owner))")
31	    OwnerDto toOwnerDto(Owner owner);
32	
33	    Owner toOwner(OwnerDto ownerDto);
34	
35	    /**
36	     * Formats the owner's stored names for display as {@code "LastName, FirstName"}.
37	     */
38	    default String formatDisplayName(Owner owner) {
39	        return owner.getLastName() + ", " + owner.getFirstName();
40	    }
41	
42	    /**
43	     * Formats the owner's initials as the upper-cased first letters of firstName and
44	     * lastName, dot-separated with a trailing dot, e.g. {@code "J.S."}.
45	     */
46	    default String formatInitials(Owner owner) {
47	        return initial(owner.getFirstName()) + initial(owner.getLastName());
48	    }
49	
50	    /** The upper-cased first letter of {@code name} followed by a dot. */
51	    private String initial(String name) {
52	        return Character.toUpperCase(name.charAt(0)) + ".";
53	    }
54	
55	    /**
56	     * Derives the owner's locality (canonical region) from its city via the fixed
57	     * city-to-region table, yielding {@code "UNKNOWN"} for any city not in the table.
58	     */
59	    default String resolveLocality(Owner owner) {
60	        return LocalityResolver.resolve(owner.getCity());
61	    }
62	
63	    /**
64	     * Formats the owner's membership number as {@code "<customerCode>-M<YY>"}, where YY is the
65	     * last two digits of the registration date year, e.g. {@code "LON-SMI-0007-M26"}.
66	     */
67	    default String formatMembershipNumber(Owner owner) {
68	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
69	    }
70	
71	    /**
72	     * Resolves the owner's numeric membership level, assigned on creation: starts at {@code 1},
73	     * plus {@code 1} when an email is present, plus {@code 1} when the owner has no namesakes
74	     * (namesakeCount is 0), capped at {@code 3} (level {@code 4} is reserved for tenure).
75	     */
76	    default Integer resolveMembershipLevel(Owner owner) {
77	        int level = 1;
78	        if (hasEmail(owner)) {
79	            level++;
80	        }
81	        if (Integer.valueOf(0).equals(owner.getNamesakeCount())) {
82	            level++;
83	        }
84	        return Math.min(level, 3);
85	    }
