87	    /**
88	     * Resolves the owner's preferred contact channel: {@code "EMAIL"} when an email is
89	     * present, otherwise {@code "PHONE"}.
90	     */
91	    default String resolveContactPreference(Owner owner) {
92	        return hasEmail(owner) ? "EMAIL" : "PHONE";
93	    }
94	
95	    /** Whether the owner has a non-blank email address. */
96	    private boolean hasEmail(Owner owner) {
97	        return owner.getEmail() != null && !owner.getEmail().isBlank();
98	    }
