118	     * the raw value normalizes to a valid E.164 number.
119	     */
120	    @Named("normalizeTelephone")
121	    default String normalizeTelephone(String telephone) {
122	        return TelephoneNormalizer.toE164(telephone);
123	    }
124	
125	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
126	
127	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
128	
129	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
