1	package org.springframework.samples.petclinic.rest.validation;
2	
3	import java.util.Comparator;
4	import java.util.List;
5	import java.util.Map;
6	import java.util.stream.Collectors;
7	
8	/**
9	 * Per-country rule for the national-number length of an E.164 telephone.
10	 *
11	 * <p>An E.164 number is a {@code '+'} followed by a country calling code and a national number.
12	 * Each country fixes how many national digits it uses; this holds those known lengths (e.g. the
13	 * {@code +61} Australian format carries 9 national digits, the {@code +1} North American format
14	 * carries 10) and checks a normalized E.164 number against them. Numbers whose country code has no
15	 * known length are left unconstrained (beyond the general E.164 shape enforced by
16	 * {@link TelephoneNormalizer#toE164(String)}).
17	 */
18	public final class E164NationalNumberRule {
19	
20	    /** Known country calling codes mapped to their required national-number digit count. */
21	    private static final Map<String, Integer> NATIONAL_LENGTHS = Map.of(
22	            "1", 10,   // North American Numbering Plan
23	            "61", 9);  // Australia
24	
25	    /** Country codes checked longest-first, so a longer code wins over a shorter prefix of it. */
26	    private static final List<String> CODES_BY_LENGTH = NATIONAL_LENGTHS.keySet().stream()
27	            .sorted(Comparator.comparingInt(String::length).reversed())
28	            .collect(Collectors.toList());
29	
30	    private E164NationalNumberRule() {
31	    }
32	
33	    /**
34	     * Whether the national number of a normalized E.164 string has the length its country code
35	     * requires. A number whose country code has no known length rule is accepted.
36	     *
37	     * @param e164 a normalized E.164 string ({@code '+'} followed by digits), as produced by
38	     *             {@link TelephoneNormalizer#toE164(String)}; may be {@code null}
39	     * @return {@code true} when the national-number length matches the country code (or the country
40	     *         code is unknown), {@code false} otherwise (including for a {@code null} input)
41	     */
42	    public static boolean hasValidNationalLength(String e164) {
43	        if (e164 == null) {
44	            return false;
45	        }
46	        String digits = e164.startsWith("+") ? e164.substring(1) : e164;
47	        for (String code : CODES_BY_LENGTH) {
48	            if (digits.startsWith(code)) {
49	                return digits.length() - code.length() == NATIONAL_LENGTHS.get(code);
50	            }
51	        }
52	        return true;
53	    }
54	}
