54	
55	    public ClinicServiceImpl(
56	        PetRepository petRepository,
57	        VetRepository vetRepository,
58	        OwnerRepository ownerRepository,
59	        VisitRepository visitRepository,
60	        SpecialtyRepository specialtyRepository,
61	        PetTypeRepository petTypeRepository,
62	        CustomerCodeGenerator customerCodeGenerator,
63	        HouseholdIdGenerator householdIdGenerator) {
