102	    }
103	
104	    @Override
105	    @Transactional
106	    public void deleteVisit(Visit visit) throws DataAccessException {
107	        visitRepository.delete(visit);
108	    }
109	
110	    @Override
111	    @Transactional(readOnly = true)
112	    public Vet findVetById(int id) throws DataAccessException {
113	        return findEntityById(() -> vetRepository.findById(id));
114	    }
115	
116	    @Override
117	    @Transactional(readOnly = true)
118	    public Collection<Vet> findAllVets() throws DataAccessException {
119	        return vetRepository.findAll();
120	    }
121	
122	    @Override
123	    @Transactional
124	    public void saveVet(Vet vet) throws DataAccessException {
125	        vetRepository.save(vet);
126	    }
127	
128	    @Override
129	    @Transactional
130	    public void deleteVet(Vet vet) throws DataAccessException {
131	        vetRepository.delete(vet);
132	    }
133	
134	    @Override
135	    @Transactional(readOnly = true)
136	    public Collection<Owner> findAllOwners() throws DataAccessException {
137	        return ownerRepository.findAll();
138	    }
139	
140	    @Override
141	    @Transactional(readOnly = true)
142	    public Page<Owner> findOwners(String lastName, Pageable pageable) throws DataAccessException {
143	        if (lastName != null) {
144	            return ownerRepository.findByLastName(lastName, pageable);
145	        }
146	        return ownerRepository.findAll(pageable);
147	    }
148	
149	    @Override
150	    @Transactional
151	    public void deleteOwner(Owner owner) throws DataAccessException {
152	        ownerRepository.delete(owner);
153	    }
154	
155	    @Override
156	    @Transactional(readOnly = true)
157	    public PetType findPetTypeById(int petTypeId) {
158	        return findEntityById(() -> petTypeRepository.findById(petTypeId));
159	    }
160	
161	    @Override
162	    @Transactional(readOnly = true)
163	    public Collection<PetType> findAllPetTypes() throws DataAccessException {
164	        return petTypeRepository.findAll();
165	    }
166	
167	    @Override
168	    @Transactional
169	    public void savePetType(PetType petType) throws DataAccessException {
170	        petTypeRepository.save(petType);
171	    }
172	
173	    @Override
174	    @Transactional
175	    public void deletePetType(PetType petType) throws DataAccessException {
176	        petTypeRepository.delete(petType);
177	    }
178	
179	    @Override
180	    @Transactional(readOnly = true)
181	    public Specialty findSpecialtyById(int specialtyId) {
182	        return findEntityById(() -> specialtyRepository.findById(specialtyId));
183	    }
184	
185	    @Override
186	    @Transactional(readOnly = true)
187	    public Collection<Specialty> findAllSpecialties() throws DataAccessException {
