235	    @Override
236	    @Transactional(readOnly = true)
237	    public Collection<Vet> findVets() throws DataAccessException {
238	        return vetRepository.findAll();
239	    }
240	
241	    @Override
242	    @Transactional
243	    public void saveOwner(Owner owner) throws DataAccessException {
244	        if (owner.isNew() && owner.getCustomerCode() == null) {
245	            long citySequence = ownerRepository.countByCityIgnoreCase(owner.getCity()) + 1;
246	            owner.setCustomerCode(customerCodeGenerator.generate(owner.getCity(), owner.getLastName(), citySequence));
247	        }
248	        ownerRepository.save(owner);
249	
250	    }
251	
252	    @Override
253	    @Transactional(readOnly = true)
254	    public boolean existsOwnerByTelephone(String telephone) throws DataAccessException {
255	        return ownerRepository.existsByTelephone(telephone);
256	    }
257	
258	    @Override
259	    @Transactional(readOnly = true)
260	    public boolean existsOwnerByEmail(String email) throws DataAccessException {
261	        return ownerRepository.existsByEmailIgnoreCase(email);
262	    }
263	
264	    @Override
265	    @Transactional(readOnly = true)
266	    public boolean existsOwnerInHousehold(String lastName, String address) throws DataAccessException {
267	        return !findHouseholdMembers(lastName, address).isEmpty();
268	    }
269	
270	    /**
271	     * The maximum number of owners allowed in a single city; once a city holds this many
272	     * owners it is considered at capacity and no further owners may be created there.
273	     */
274	    static final long CITY_CAPACITY = 50;
275	
276	    @Override
277	    @Transactional(readOnly = true)
278	    public boolean isCityAtCapacity(String city) throws DataAccessException {
279	        return ownerRepository.countByCityIgnoreCase(city) >= CITY_CAPACITY;
280	    }
281	
282	    /**
283	     * The maximum number of owners that may be created in a single day; once this many owners
284	     * have already been registered on a given business day no further owners may be created for
285	     * that day.
286	     */
287	    static final long DAILY_OWNER_LIMIT = 100;
288	
289	    @Override
290	    public LocalDate resolveRegistrationDate(LocalDate registrationDate) {
291	        LocalDate effectiveDate = registrationDate == null ? LocalDate.now() : registrationDate;
292	        return BusinessDay.rollForward(effectiveDate);
293	    }
294	
295	    @Override
296	    @Transactional(readOnly = true)
297	    public boolean isDailyOwnerLimitReached(LocalDate registrationDate) throws DataAccessException {
298	        return ownerRepository.countByRegistrationDate(registrationDate) >= DAILY_OWNER_LIMIT;
299	    }
300	
301	    /**
302	     * The number of owners that may be registered on a given day before further sign-ups for that
303	     * day are flagged with a bulk-signup warning. Once more than this many owners already exist for
304	     * the day, subsequent creates carry the warning.
305	     */
306	    static final long BULK_SIGNUP_WARNING_THRESHOLD = 80;
307	
308	    @Override
309	    @Transactional(readOnly = true)
310	    public boolean isBulkSignupWarranted(LocalDate registrationDate) throws DataAccessException {
311	        return ownerRepository.countByRegistrationDate(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD;
312	    }
313	
314	    @Override
315	    @Transactional(readOnly = true)
316	    public long countNamesakes(String firstName, String lastName) throws DataAccessException {
317	        return ownerRepository.findByLastNameIgnoreCase(lastName).stream()
318	            .filter(owner -> owner.getFirstName().equalsIgnoreCase(firstName))
319	            .count();
320	    }
321	
322	    @Override
323	    @Transactional
324	    public String assignHousehold(Owner owner) throws DataAccessException {
325	        List<Owner> members = findHouseholdMembers(owner.getLastName(), owner.getAddress());
326	        String householdId = members.stream()
327	            .map(Owner::getHouseholdId)
328	            .filter(Objects::nonNull)
329	            .findFirst()
330	            .orElseGet(() -> householdIdGenerator.generate(owner.getLastName(), owner.getAddress()));
331	        owner.setHouseholdId(householdId);
332	        for (Owner member : members) {
333	            if (member.getHouseholdId() == null) {
334	                member.setHouseholdId(householdId);
335	                ownerRepository.save(member);
336	            }
337	        }
338	        return householdId;
339	    }
340	
341	    /**
342	     * The number of members the owner's household will have once this (not yet persisted) owner is
343	     * created: the existing members sharing its last name and canonical address, plus the owner itself.
344	     */
345	    @Override
346	    @Transactional(readOnly = true)
347	    public long countHouseholdMembers(String lastName, String address) throws DataAccessException {
348	        return findHouseholdMembers(lastName, address).size() + 1;
349	    }
350	
351	    /**
352	     * Find the existing owners that share {@code owner}'s household, i.e. those with the same last
353	     * name (ignoring case) and the same canonical address.
354	     */
355	    private List<Owner> findHouseholdMembers(String lastName, String address) {
356	        String canonicalAddress = householdIdGenerator.canonical(address);
357	        return ownerRepository.findByLastNameIgnoreCase(lastName).stream()
358	            .filter(owner -> householdIdGenerator.canonical(owner.getAddress()).equals(canonicalAddress))
359	            .toList();
360	    }
361	
362	    @Override
363	    @Transactional(readOnly = true)
364	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
365	        return ownerRepository.findByLastName(lastName);
366	    }
367	
368	    @Override
369	    @Transactional(readOnly = true)
370	    public Collection<Visit> findVisitsByPetId(int petId) {
371	        return visitRepository.findByPetId(petId);
372	    }
373	
374	    @Override
375	    @Transactional(readOnly = true)
376	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
377	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
378	    }
379	
380	    private <T> T findEntityById(Supplier<T> supplier) {
381	        try {
382	            return supplier.get();
383	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
384	            // Just ignore not found exceptions for Jdbc/Jpa realization
385	            return null;
386	        }
387	    }
388	
389	}
